//! The T6 zone walk: the runtime half. `walk_gen.rs` (generated by
//! `gen/t6gen.py`) holds one load function per asset structure; it calls the
//! primitives here, which implement the game's pointer rules:
//!
//! - an asset header loads into TEMP (when its rules say so), its members
//!   into VIRTUAL; members can name another block;
//! - a pointer is null, "follows" (-1, data next in the stream), "insert"
//!   (-2, follows and is reachable through an alias slot in VIRTUAL; only in
//!   TEMP contexts) or an offset into data loaded earlier;
//! - field references in counts and conditions read the most recently
//!   entered instance of the named structure, as the game's own loader does.

use crate::xasset_kind::XAssetKind;
use crate::asset_dir::AssetDirectory;
use crate::walk_gen;
use crate::zone_core::{RawRef, LoadResult, ARCHIVE_SEGMENT_SCRATCH, ZoneReadFault, StreamRef, ZoneByteReader};

const MAX_DEPTH: u32 = 96;

/// One asset load, as the walk saw it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Loaded {
    pub ty: XAssetKind,
    /// Where the asset's header was loaded. For assets whose header goes to
    /// TEMP this is only valid inside `asset_loaded`.
    pub body: RawRef,
    /// The pointer slot that named it (now pointing at `body`).
    pub bay: RawRef,
    /// The VIRTUAL slot later references go through, when the load was an
    /// insert; stable for the whole zone.
    pub alias: Option<RawRef>,
    /// Loads are numbered 1, 2, ... in the order they finish; this is this
    /// load's number.
    pub serial: u64,
    /// The number of loads finished when this one began: nested loads of
    /// this asset have serials above it.
    pub started: u64,
}

/// What a walk reports while it reads; every method has a no-op default.
pub trait WalkSink {
    /// An asset (top-level or nested) finished loading.
    fn asset_loaded(&mut self, s: &ZoneByteReader<'_>, loaded: Loaded) -> LoadResult<()> {
        let _ = (s, loaded);
        Ok(())
    }

    /// Top-level asset `index` of the asset list is about to load.
    fn begin_asset(&mut self, s: &ZoneByteReader<'_>, asset_ix: usize, ty: XAssetKind) {
        let _ = (s, asset_ix, ty);
    }
}

pub struct NoSink;

impl WalkSink for NoSink {}

pub struct Walker<'w, 'a> {
    pub(crate) s: &'w mut ZoneByteReader<'a>,
    loads: u64,
    cur: [RawRef; walk_gen::TYPE_COUNT],
    depth: u32,
    trail: [u16; MAX_DEPTH as usize + 1],
    sink: &'w mut dyn WalkSink,
}

/// Field widths the generated code reads for counts and conditions. The
/// current rules never read 64-bit or float fields; the walk keeps them so a
/// regenerated walk can.
#[allow(dead_code)]
#[derive(Clone, Copy)]
pub(crate) enum Kind {
    U8,
    I8,
    U16,
    I16,
    U32,
    I32,
    U64,
    I64,
    F32,
}

impl<'w, 'a> Walker<'w, 'a> {
    pub fn new(s: &'w mut ZoneByteReader<'a>, sink: &'w mut dyn WalkSink) -> Self {
        Walker {
            s,
            loads: 0,
            cur: [RawRef {
                seg: 0,
                offset: 0,
            }; walk_gen::TYPE_COUNT],
            depth: 0,
            trail: [0; MAX_DEPTH as usize + 1],
            sink,
        }
    }

    /// The structures being loaded, outermost first; after a failed walk this
    /// is where it failed.
    pub fn trail(&self) -> impl Iterator<Item = &'static str> + '_ {
        self.trail[..self.depth as usize]
            .iter()
            .map(|&t| walk_gen::TYPE_NAMES[t as usize])
    }

    pub fn stream(&self) -> &ZoneByteReader<'a> {
        self.s
    }

    pub(crate) fn enter(&mut self, ty: usize, base_at: RawRef) -> LoadResult<()> {
        self.cur[ty] = base_at;
        if self.depth >= MAX_DEPTH {
            return Err(ZoneReadFault::WalkTooDeep);
        }
        self.trail[self.depth as usize] = ty as u16;
        self.depth += 1;
        Ok(())
    }

    pub(crate) fn leave(&mut self) {
        self.depth -= 1;
    }

    /// Read a field of the current instance of structure `ty`.
    pub(crate) fn rd(&self, ty: usize, off: usize, kind: Kind) -> LoadResult<i64> {
        self.rd_at(self.cur[ty], off, kind)
    }

    /// Read a field behind a pointer member (at `link_off`) of the current
    /// instance of `ty`; the pointee was loaded earlier in the walk.
    pub(crate) fn rd_through(
        &self,
        ty: usize,
        link_off: usize,
        off: usize,
        kind: Kind,
    ) -> LoadResult<i64> {
        let raw = self.s.uint_from_bytes(self.cur[ty], link_off)?;
        match StreamRef::from_word(raw) {
            StreamRef::At(p) => self.rd_at(self.s.follow_entry_link(p), off, kind),
            _ => Err(ZoneReadFault::BadPointer {
                what: "count read through an unloaded pointer",
                raw,
            }),
        }
    }

    fn rd_at(&self, p: RawRef, off: usize, kind: Kind) -> LoadResult<i64> {
        Ok(match kind {
            Kind::U8 => self.s.u8_at(p, off)? as i64,
            Kind::I8 => self.s.u8_at(p, off)? as i8 as i64,
            Kind::U16 => self.s.ushort_from_bytes(p, off)? as i64,
            Kind::I16 => self.s.short_from_bytes(p, off)? as i64,
            Kind::U32 => self.s.uint_from_bytes(p, off)? as i64,
            Kind::I32 => self.s.int_from_bytes(p, off)? as i64,
            Kind::U64 => {
                let lo = self.s.uint_from_bytes(p, off)? as u64;
                let hi = self.s.uint_from_bytes(p, off + 4)? as u64;
                (lo | hi << 32) as i64
            }
            Kind::I64 => {
                let lo = self.s.uint_from_bytes(p, off)? as u64;
                let hi = self.s.uint_from_bytes(p, off + 4)? as u64;
                (lo | hi << 32) as i64
            }
            Kind::F32 => self.s.float_from_bytes(p, off)? as i64,
        })
    }

    pub(crate) fn count(&self, n: i64) -> LoadResult<usize> {
        if !(0..=0x1000_0000).contains(&n) {
            return Err(ZoneReadFault::BadCount(n));
        }
        Ok(n as usize)
    }

    pub(crate) fn div(a: i64, b: i64) -> LoadResult<i64> {
        if b == 0 {
            return Err(ZoneReadFault::DivideByZero);
        }
        Ok(a / b)
    }

    #[allow(dead_code)]
    pub(crate) fn rem(a: i64, b: i64) -> LoadResult<i64> {
        if b == 0 {
            return Err(ZoneReadFault::DivideByZero);
        }
        Ok(a % b)
    }

    /// Read `size` bytes into the block at `p`, which must be the block's
    /// current write position.
    pub(crate) fn load_at(&mut self, land_at: RawRef, span_len: usize) -> LoadResult<()> {
        let top = self.s.top_block()?;
        let pos = self.s.write_pos(top as u8);
        if land_at.seg as usize != top || land_at.offset as usize != pos {
            return Err(ZoneReadFault::NonContiguous {
                block: land_at.seg as usize,
                at: land_at.offset as usize,
                expected: pos,
            });
        }
        self.s.load_bytes(span_len)?;
        Ok(())
    }

    pub(crate) fn put(&mut self, seg_ix: usize) -> LoadResult<()> {
        self.s.put(seg_ix)
    }

    pub(crate) fn pop(&mut self) -> LoadResult<()> {
        self.s.pop()
    }

    #[allow(dead_code)]
    pub(crate) fn ptr(&self, bay: RawRef) -> LoadResult<StreamRef> {
        self.s.address_for(bay, 0)
    }

    /// A pointer that names data loaded earlier.
    fn reuse(&mut self, p: RawRef) {
        self.s.record_displacement(p);
    }

    /// The member-pointer rule for single and array pointers and allocated
    /// pointer arrays: null check, optional reuse, allocation, and (in TEMP
    /// contexts) the insert alias. `body` loads the pointee at the
    /// allocation.
    pub(crate) fn member_ptr(
        &mut self,
        bay: RawRef,
        reusable: bool,
        in_temp: bool,
        align: usize,
        body: impl FnOnce(&mut Self, RawRef) -> LoadResult<()>,
    ) -> LoadResult<()> {
        let raw = self.s.uint_from_bytes(bay, 0)?;
        let insert = match StreamRef::from_word(raw) {
            StreamRef::Null => return Ok(()),
            StreamRef::Following => false,
            StreamRef::Insert if in_temp => true,
            StreamRef::Insert => {
                return Err(ZoneReadFault::BadPointer {
                    what: "insert outside a temp block",
                    raw,
                });
            }
            StreamRef::At(prior) => {
                if !reusable {
                    return Err(ZoneReadFault::BadPointer {
                        what: "offset on a pointer that never reuses data",
                        raw,
                    });
                }
                self.reuse(prior);
                return Ok(());
            }
        };
        let at = self.s.align_alloc(align)?;
        let alias = self.open_alias(insert)?;
        body(self, at)?;
        self.close_alias(alias, at)?;
        self.s.repair_cell(bay, at)
    }

    /// An insert pointer takes an alias slot before its body loads.
    fn open_alias(&mut self, insert: bool) -> LoadResult<Option<RawRef>> {
        insert.then(|| self.s.patch_reference_cell()).transpose()
    }

    /// Points the alias taken by `open_alias` (if any) at the loaded body.
    fn close_alias(&mut self, alias_ptr: Option<RawRef>, at: RawRef) -> LoadResult<()> {
        alias_ptr.map_or(Ok(()), |a| self.s.bind_insert(a, at))
    }

    /// The asset-pointer rule (`LoadPtr` of an asset structure).
    pub(crate) fn asset_ptr(
        &mut self,
        bay: RawRef,
        ty: usize,
        in_temp: bool,
        align: usize,
        load: fn(&mut Self, RawRef, bool) -> LoadResult<()>,
    ) -> LoadResult<()> {
        if in_temp {
            self.put(ARCHIVE_SEGMENT_SCRATCH)?;
        }
        let raw = self.s.uint_from_bytes(bay, 0)?;
        match StreamRef::from_word(raw) {
            StreamRef::Null => {}
            StreamRef::Following | StreamRef::Insert => {
                let insert = matches!(StreamRef::from_word(raw), StreamRef::Insert);
                if insert && !in_temp {
                    return Err(ZoneReadFault::BadPointer {
                        what: "insert on an asset outside a temp block",
                        raw,
                    });
                }
                let at = self.s.align_alloc(align)?;
                let alias = self.open_alias(insert)?;
                let started = self.loads;
                load(self, at, true)?;
                self.loads += 1;
                self.close_alias(alias, at)?;
                self.s.repair_cell(bay, at)?;
                if let Some(asset) = walk_gen::ASSET_OF_TYPE[ty] {
                    let loaded = Loaded {
                        ty: asset,
                        body: at,
                        bay,
                        alias,
                        serial: self.loads,
                        started,
                    };
                    self.sink.asset_loaded(self.s, loaded)?;
                }
            }
            StreamRef::At(p) => self.reuse(p),
        }
        if in_temp {
            self.pop()?;
        }
        Ok(())
    }

    /// One element of a pointer array to a non-asset structure.
    pub(crate) fn elem_ptr(
        &mut self,
        bay: RawRef,
        reusable: bool,
        align: usize,
        body: impl FnOnce(&mut Self, RawRef) -> LoadResult<()>,
    ) -> LoadResult<()> {
        let raw = self.s.uint_from_bytes(bay, 0)?;
        match StreamRef::from_word(raw) {
            StreamRef::Null => Ok(()),
            StreamRef::Following => {
                let at = self.s.align_alloc(align)?;
                body(self, at)?;
                self.s.repair_cell(bay, at)
            }
            StreamRef::At(p) if reusable => {
                self.reuse(p);
                Ok(())
            }
            _ => Err(ZoneReadFault::BadPointer {
                what: "pointer-array element",
                raw,
            }),
        }
    }

    /// `LoadXString`: a string pointer that is null, follows, or reuses.
    pub(crate) fn xstring(&mut self, str_ref: RawRef) -> LoadResult<()> {
        let raw = self.s.uint_from_bytes(str_ref, 0)?;
        match StreamRef::from_word(raw) {
            StreamRef::Null => Ok(()),
            StreamRef::Following => {
                let at = self.s.align_alloc(1)?;
                let body = self.s.read_text_value()?;
                debug_assert_eq!(at, body);
                self.s.repair_cell(str_ref, body)
            }
            StreamRef::At(prior) => {
                self.reuse(prior);
                Ok(())
            }
            StreamRef::Insert => Err(ZoneReadFault::BadPointer {
                what: "string",
                raw,
            }),
        }
    }

    /// `count` string pointers in a row at `arr`, each loaded in turn.
    pub(crate) fn xstrings(&mut self, arr: RawRef, n_strs: usize) -> LoadResult<()> {
        for i in 0..n_strs {
            self.xstring(arr.shifted_by(i * 4))?;
        }
        Ok(())
    }

    /// Walk every asset of an opened asset list in order; leaves the stream
    /// where the last asset ended and pops the list's VIRTUAL block.
    pub fn walk_assets(&mut self, table: &AssetDirectory) -> LoadResult<()> {
        for str_ix in 0..table.count() {
            let ty = table.asset_type_at(self.s, str_ix)?;
            let slot = table.bay(str_ix).ok_or(ZoneReadFault::NothingPushedYet)?;
            self.sink.begin_asset(self.s, str_ix, ty);
            walk_gen::load_xasset(self, ty, slot)?;
        }
        self.s.pop()
    }
}
